    return tide_add_d3(tide_add_d3(tide_mul_d3(m.c0, tide_d3_splat(v.x)), tide_mul_d3(m.c1, tide_d3_splat(v.y))),
                       tide_mul_d3(m.c2, tide_d3_splat(v.z)));
